WITH filtered AS (SELECT id, name, email, country, city, segment, signup_date, is_active, age, CASE WHEN is_active THEN 'Yes' ELSE 'No' END AS is_active_label, COALESCE(city, 'N/A') AS city_clean FROM customers WHERE signup_date >= TO_DATE('2023-09-13') AND segment IS NOT NULL) SELECT id, segment, is_active, city_clean, DENSE_RANK() OVER w_part AS age_dense_rank, LAST_VALUE(age) IGNORE NULLS OVER (PARTITION BY country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_age FROM filtered WINDOW w_part AS (PARTITION BY country, segment ORDER BY age DESC NULLS LAST);
